      .map(|e| e.to_string_lossy().to_string())
      .unwrap_or_default();

    if !CAPABILITY_FILE_EXTENSIONS.contains(&ext.as_str()) {
      continue;
    }

    let capability_file = CapabilityFile::load(&path)?;

    let caps = match capability_file {
      CapabilityFile::Capability(cap) => vec![cap],
      CapabilityFile::List(list) => list,
      CapabilityFile::NamedList { capabilities: caps } => caps,
    };

    for cap in caps {
      if capabilities.contains_key(&cap.identifier) {
        return Err(Error::CapabilityAlreadyExists {
          identifier: cap.identifier,
        });
      }
      capabilities.insert(cap.identifier.clone(), cap);
    }
  }

  Ok(capabilities)
}
